e:9px;line-height:1.5;min-height:37px}.log-mark{color:#e8bc72}.right-rail{display:flex;flex-direction:column;gap:13px}.tower-card,.journal-card{padding:17px 16px}.tower-display{position:relative;display:flex;align-items:center;gap:11px;height:88px;margin-top:4px;overflow:hidden}.tower-line{position:absolute;left:15px;top:15px;bottom:8px;width:1px;background:linear-gradient(#e8bc72,#635373,#34394b)}.tower-glow{position:absolute;left:0;top:23px;width:34px;height:43px;background:#dfb46a33;filter:blur(13px)}.tower-icon{position:relative;margin-left:4px;width:23px;height:23px;display:grid;place-items:center;color:#f0ca85;font-size:17px;background:#302a35;border:1px solid #665244;border-radius:50%}.tower-display>div:last-child{display:grid;gap:2px}.tower-display strong{font:28px 'Playfair Display',serif;color:#f0dfc4}.tower-display span{font:8px 'DM Mono',monospace;letter-spacing:.16em;color:#8e95a6}.tower-progress{display:flex;justify-content:space-between;align-items:center;font:8px 'DM Mono',monospace;letter-spacing:.08em;color:#8c93a5;margin:1px 0 8px}.tower-progress strong{color:#d8d0c3;font-size:8px;letter-spacing:0;font-weight:400}.progress-track{height:4px;background:#303446;border-radius:3px;overflow:hidden}.progress-track i{display:block;width:8%;height:100%;background:linear-gradient(90deg,#b88c57,#eed18e);border-radius:4px;transition:width .4s}.tower-note{font-size:9px;color:#8d93a3;margin-top:12px;line-height:1.5}.tower-note b{color:#d6b17c;font-weight:600}.live-label{font-size:8px;color:#8ec59e;letter-spacing:.08em}.live-label i{width:5px;height:5px;margin-right:3px}.journal-list{margin-top:14px}.journal-item{display:flex;align-items:center;gap:9px;position:relative;min-height:45px}.journal-item:not(:last-child):before{content:"";position:absolute;left:11px;top:31px;width:1px;height:20px;background:#414354}.journal-item>span{width:22px;height:22px;border-radius:50%;border:1px solid #776149;background:#302b34;color:#e6c28a;display:grid;place-items:center;font