odal h2,.over-modal h2{font:600 27px 'Playfair Display',serif;margin:7px 0;color:#f0e2cc}.shop-intro{font:italic 11px 'Playfair Display',serif;color:#aaa7b0;margin:0}.shop-gold{display:inline-flex;margin-top:14px;padding:7px 10px;border:1px solid #5b4b3b;border-radius:5px;background:#302c31;color:#edc980;font:11px 'DM Mono',monospace}.shop-items{display:grid;gap:7px;margin:15px 0}.shop-item{display:flex;align-items:center;gap:10px;padding:10px;background:#1a1f2d;border:1px solid #383e50;border-radius:7px}.shop-item-icon{width:31px;height:31px;display:grid;place-items:center;border-radius:7px;background:#332a35;color:#e9958c;font-size:16px}.shop-item-copy{display:grid;gap:3px;flex:1}.shop-item-copy strong{font-size:10px}.shop-item-copy small{font-size:8px;color:#969cac}.buy-btn{border:1px solid #786044;background:#40372f;color:#f0cc8c;padding:7px 10px;border-radius:5px;font:9px 'DM Mono',monospace;cursor:pointer;white-space:nowrap}.buy-btn:hover:not(:disabled){background:#564635}.buy-btn:disabled{opacity:.4;cursor:not-allowed}.continue-btn{width:100%;display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border:1px solid #987448;border-radius:6px;background:linear-gradient(100deg,#72563b,#59453a);color:#fff0d6;font-weight:700;font-size:11px;cursor:pointer}.continue-btn:hover{filter:brightness(1.13)}.continue-btn span{font-size:18px}.shop-small{text-align:center;color:#858b9a;font-size:8px;margin-top:10px}.over-modal{text-align:center;max-width:390px;padding:31px}.over-icon{font-size:34px;color:#e8bc72;margin-bottom:9px}.over-modal h2{font-size:25px}.over-modal p{font-size:11px;color:#a2a6b2;line-height:1.6}.over-record{display:flex;justify-content:space-between;align-items:center;padding:12px 15px;border:1px solid #3c4050;border-radius:6px;margin:18px 0;color:#9ba1af;font:9px 'DM Mono',monospace;letter-spacing:.1em}.over-record strong{font:22px 'Playfair Display',serif;color:#edc982}@keyframes pulse{50%{transform:scale(1.14);opacity:.7}}@keyframes float{50%{transform:translateY(-7px)}}@keyframes hit{25%{transform:translateX(calc(-50% + 9px))}50%{transform:translateX(calc(-50% - 8px))}75%{transform:translateX(calc(-50% + 4px))}}@keyframes floatUp{0%{opacity:0;transform:translate(-50%,10px)}15%{opacity:1}100%{opacity:0;transform:translate(-50%,-52px)}}@keyframes fadeIn{from{opacity:0}to{opacity:1}}
