color:#d8d0c3;font-size:8px;letter-spacing:0;font-weight:400}
.progress-track{
height:4px;background:#303446;border-radius:3px;overflow:hidden}
.progress-track i{
display:block;width:8%;height:100%;background:linear-gradient(90deg,#b88c57,#eed18e);border-radius:4px;transition:width .4s}
.tower-note{
font-size:9px;color:#8d93a3;margin-top:12px;line-height:1.5}
.tower-note b{
color:#d6b17c;font-weight:600}
.live-label{
font-size:8px;color:#8ec59e;letter-spacing:.08em}
.live-label i{
width:5px;height:5px;margin-right:3px}
.journal-list{
margin-top:14px}
.journal-item{
display:flex;align-items:center;gap:9px;position:relative;min-height:45px}
.journal-item:not(:last-child):before{
content:"";position:absolute;left:11px;top:31px;width:1px;height:20px;background:#414354}
.journal-item>span{
width:22px;height:22px;border-radius:50%;border:1px solid #776149;background:#302b34;color:#e6c28a;display:grid;place-items:center;font:8px 'DM Mono',monospace;flex:none}
.journal-item div{
display:grid;gap:3px}
.journal-item strong{
font-size:9px;color:#e1dbd1;font-weight:600}
.journal-item small{
font-size:8px;color:#878d9e}
.journal-item>i{
margin-left:auto;color:#dfb975;font-style:normal;font-size:8px}
.journal-item.locked>span{
border-color:#414557;background:#202433;color:#737b8f}
.journal-item.locked strong{
color:#83899a}
.journal-item.locked>i{
color:#62697d}
.journal-foot{
border-top:1px solid #303446;margin-top:9px;padding-top:10px;color:#747b8e;font-size:8px;text-align:center}
.quote-card{
padding:17px 15px;background:linear-gradient(120deg,#292536,#1c2030);border:1px solid #3b3848;border-radius:9px;display:grid;gap:9px}
.quote-card span{
font-family:'Playfair Display',serif;color:#d7c8b3;font-style:italic;font-size:12px;line-height:1.6}
.quote-card i{
font:8px 'DM Mono',monospace;color:#a17e61;letter-spacing:.12em;font-style:normal}
footer{
display:flex;justify-content:space-between;align-items:center;margin-top:19px;color:#6f7588;font:8px 'DM Mono',monospace;letter-spacing:.1em}
footer b{
color:#b79765}
footer button{
border:0;background:none;color:#9196a4;font:9px Manrope,sans-serif;cursor:pointer}
footer button:hover{
color:#e8bc72}
.modal-backdrop{
position:fixed;z-index:20;inset:0;background:#090b12ce;backdrop-filter:blur(7px);display:grid;place-items:center;padding:18px;animation:fadeIn .2s}
.modal-backdrop.hidden{
display:none}
.shop-modal,.over-modal{
width:min(480px,100%);padding:24px 26px;background:linear-gradient(145deg,#222637,#171b28);border-color:#514554;box-shadow:0 25px 100px #000b}
.shop-top{
display:flex;justify-content:space-between;align-items:start;margin-bottom:12px}
.shop-emblem{
width:40px;height:40px;border:1px solid #735b45;border-radius:11px;display:grid;place-items:center;background:linear-gradient(145deg,#443236,#282735);font-size:21px;color:#e9c88d}
.close-shop{
width:29px;height:29px;border:1px solid #414558;border-radius:50%;background:#202433;color:#a8adba;font-size:19px;cursor:pointer}
.shop-modal h2,.over-modal h2{
font:600 27px 'Playfair Display',serif;margin:7px 0;color:#f0e2cc}
.shop-intro{
font:italic 11px 'Playfair Display',serif;color:#aaa7b0;margin:0}
.shop-gold{
display:inline-flex;margin-top:14px;padding:7px 10px;border:1px solid #5b4b3b;border-radius:5px;background:#302c31;color:#edc980;font:11px 'DM Mono',monospace}
.shop-items{
display:grid;gap:7px;margin:15px 0}
.shop-item{
display:flex;align-items:center;gap:10px;padding:10px;background:#1a1f2d;border:1px solid #383e50;border-radius:7px}
.shop-item-icon{
width:31px;height:31px;display:grid;place-items:center;border-radius:7px;background:#332a35;color:#e9958c;font-size:16px}
.shop-item-copy{
display:grid;gap:3px;flex:1}
.shop-item-copy strong{
font-size:10px}
.shop-item-copy small{
font-size:8px;color:#969cac}
.buy-btn{
border:1px solid #786044;background:#40372f;color:#f0cc8c;padding:7px 10px;border-radius:5px;font:9px 'DM Mono',monospace;cursor:pointer;white-space:nowrap}
.buy-btn:hover:not(:disabled){
background:#564635}
.buy-btn:disabled{
opacity:.4;cursor:not-allowed}
.continue-btn{
width:100%;display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border:1px solid #987448;border-radius:6px;background:linear-gradient(100deg,#72563b,#59453a);color:#fff0d6;font-weight:700;font-size:11px;cursor:pointer}
.continue-btn:hover{
filter:brightness(1.13)}
.continue-btn span{
font-size:18px}
.shop-small{
text-align:center;color:#858b9a;font-size:8px;margin-top:10px}
.over-modal{
text-align:center;max-width:390px;padding:31px}
.over-icon{
font-size:34px;color:#e8bc72;margin-bottom:9px}
.over-modal h2{
font-size:25px}
.over-modal p{
font-size:11px;color:#a2a6b2;line-height:1.6}
.over-record{
display:flex;justify-content:space-between;align-items:center;padding:12px 15px;border:1px solid #3c4050;border-radius:6px;margin:18px 0;color:#9ba1af;font:9px 'DM Mono',monospace;letter-spacing:.1em}
.over-record strong{
font:22px 'Playfair Display',serif;color:#edc982}
@keyframes pulse{
50%{
transform:scale(1.14);opacity:.7}
}
@keyframes float{
50%{
transform:translateY(-7px)}
}
@keyframes hit{
25%{
transform:translateX(calc(-50% + 9px))}
50%{
transform:translateX(calc(-50% - 8px))}
75%{
transform:translateX(calc(-50% + 4px))}
}
@keyframes floatUp{
0%{
opacity:0;transform:translate(-50%,10px)}
15%{
opacity:1}
100%{
opacity:0;transform:translate(-50%,-52px)}
}
@keyframes fadeIn{
from{
opacity:0}
to{
opacity:1}
}

@media(max-width:1100px){
.game-layout{
grid-template-columns:220px minmax(390px,1fr)}
.right-rail{
grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr 1fr}
.tower-card,.journal-card{
min-height:190px}
.quote-card{
align-self:stretch}
.hero-panel{
grid-row:span 1}
}

@media(max-width:720px){
.app{
padding:17px 14px calc(22px + env(safe-area-inset-bottom))}
.topbar{
margin-bottom:19px}
.intro{
margin-bottom:17px}
.intro h1{
font-size:29px}
.intro p{
max-width:270px;line-height:1.6}
.run-stats{
font-size:8px}
.game-layout{
display:flex;flex-direction:column;gap:12px}
.battle-panel{
order:1;padding:15px 13px 12px}
.hero-panel{
order:2}
.right-rail{
order:3;display:grid;grid-template-columns:1fr 1fr;gap:10px}
.quote-card{
grid-column:1/-1}
.hero-panel{
padding:15px}
.hero-art{
height:135px;margin:12px -2px}
.arena{
height:215px}
.battle-heading h2{
font-size:19px}
.turn-badge{
font-size:7px}
.actions{
gap:6px}
.action-card{
padding:6px;gap:6px}
.action-copy strong{
font-size:9px}
.action-copy small{
font-size:7px}
.action-icon{
width:25px;height:25px}
.action-cost{
font-size:7px}
.action-head{
font-size:8px}
.right-rail .tower-card,.right-rail .journal-card{
padding:14px 12px;min-height:175px}
.tower-note{
font-size:8px}
.journal-item{
gap:6px}
.journal-item strong{
font-size:8px}
.quote-card{
padding:13px 14px}
footer{
flex-wrap:wrap;gap:10px;font-size:7px}
footer button{
order:3;width:100%;padding:8px}
.shop-modal{
padding:20px}
.modal-backdrop{
align-items:center}
}

@media(max-width:380px){
.app{
padding-left:10px;padding-right:10px}
.intro h1{
font-size:26px}
.run-stats{
max-width:100px}
.top-pill{
padding:7px 8px}
.battle-panel{
padding-left:10px;padding-right:10px}
.action-copy small{
white-space:normal}
.actions{
grid-template-columns:1fr 1fr}
.right-rail{
grid-template-columns:1fr}
.quote-card{
grid-column:auto}
.action-card{
min-height:53px}
}

