/* Keep the player's resources beside the encounter and make tall dialogs scroll on touch screens. */
.combat-vitals{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:0 0 13px;padding:10px 12px;border:1px solid #34394b;border-radius:7px;background:#151925}
.combat-vitals .vitals{margin:0;min-width:0}
.combat-vitals .vital-head{font-size:9px}
.modal-backdrop{overflow-y:auto;overscroll-behavior-y:contain;-webkit-overflow-scrolling:touch;align-items:start;padding:18px max(18px,env(safe-area-inset-right)) 18px max(18px,env(safe-area-inset-left))}
.shop-modal,.over-modal{max-height:calc(100vh - 36px);max-height:calc(100dvh - 36px);overflow-y:auto;overscroll-behavior:contain;-webkit-overflow-scrolling:touch;margin:auto}
@media(max-width:720px){
  .combat-vitals{gap:9px;margin-bottom:11px;padding:9px 10px}
  .combat-vitals .vital-head{font-size:8px;letter-spacing:.03em}
  .modal-backdrop{padding-top:max(12px,env(safe-area-inset-top));padding-bottom:max(12px,env(safe-area-inset-bottom))}
  .shop-modal,.over-modal{max-height:calc(100vh - 24px);max-height:calc(100dvh - 24px)}
}

